#include <stdio.h>

int main(void) {
    // 처음 재고와 다시 센 재고예요.
    int stock = 2;
    int counted = 5;
    // 아래 두 줄의 순서를 바꿔 정정한 재고보다 하나 큰 값을 shown에 저장하세요.
    // 먼저 정정해야 다음 줄의 계산이 정정한 재고를 읽어요.
    stock = counted;
    int shown = stock + 1;
    // stock, shown 순서로 두 값을 표시해요.
    printf("%d %d", stock, shown);
    return 0;
}

